        setTimeout(() => toastEl.classList.remove('show'), 2000);
      }

      function formatSize(bytes) {
        if (bytes === 0) return '0 B';
        const k = 1024;
        const sizes = ['B', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
      }

      function resetDownloadSection() {
        downloadSection.classList.add('hidden');
        passwordError.textContent = '';
        checkPassword.value = '';
      }

      function showDownloadUI(token, fileData) {
        downloadSection.classList.remove('hidden');
        downloadFileName.textContent = fileData.fileName;
        downloadFileSize.textContent = formatSize(fileData.fileSize);
        shareArea.classList.add('hidden');
        checkPassword.value = '';
        passwordError.textContent = '';
        downloadBtn.dataset.token = token;
      }

      // ---- upload ----
      uploadBtn.onclick = async () => {
        const file = fileInput.files[0];
        const password = passwordInput.value.trim();

        if (!file) {
          alert('Please select a file first.');
          return;
        }
        if (!password) {
          alert('Please set a password for download protection.');
          return;
        }

        try {
          const blob = new Blob([await file.arrayBuffer()], { type: file.type });
          const token = Math.random().toString(36).substring(2, 12) + Math.random().toString(36).substring(2, 12);

          fileStorage.set(token, {
            blob: blob,
            fileName: file.name,
            fileSize: file.size,
            password: password
          });

          const baseUrl = window.location.origin + window.location.pathname;
          const shareUrl = `${baseUrl}#token=${token}`;

          shareArea.classList.remove('hidden');
          shareLinkInput.value = shareUrl;
          uploadedFileInfo.innerHTML = `📄 ${file.name} · ${formatSize(file.size)} · password protected`;

          // if there's a hash, clear it so user sees their upload
          if (window.location.hash) {
            history.replaceState(null, '', window.location.pathname);
          }
          resetDownloadSection();

          showToast('Upload complete! Link ready.');
        } catch (err) {
          console.error(err);
          alert('Upload failed: ' + err.message);
        }
      };

      // ---- copy link ----
      copyLinkBtn.onclick = () => {
        if (!shareLinkInput.value) return;
        navigator.clipboard.writeText(shareLinkInput.value).then(() => {
          showToast('Link copied to clipboard');
        }).catch(() => {
          shareLinkInput.select();
          document.execCommand('copy');
          showToast('Link copied');
        });
      };

      // ---- download ----
      downloadBtn.onclick = () => {
        const token = downloadBtn.dataset.token;
        if (!token) {
          passwordError.textContent = 'File reference missing.';
          return;
        }
        const fileData = fileStorage.get(token);
        if (!fileData) {
          passwordError.textContent = 'File no longer available.';
          return;
        }

        const enteredPassword = checkPassword.value.trim();
        if (!enteredPassword) {
          passwordError.textContent = 'Please enter the password.';
          return;
        }

        if (enteredPassword !== fileData.password) {
          passwordError.textContent = 'Incorrect password. Try again.';
          return;
        }

        passwordError.textContent = '';
        try {
          const url = URL.createObjectURL(fileData.blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = fileData.fileName || 'download';
          document.body.appendChild(a);
          a.click();
          document.body.removeChild(a);
          setTimeout(() => URL.revokeObjectURL(url), 2000);
          showToast('Download started');
        } catch (err) {
          console.error(err);
          passwordError.textContent = 'Download failed: ' + err.message;
        }
      };

      // ---- check for token on load / hash change ----
      function checkHash() {
        const hash = window.location.hash;
        if (hash.startsWith('#token=')) {
          const token = hash.substring(7);
          const fileData = fileStorage.get(token);
          if (fileData) {
            showDownloadUI(token, fileData);
          } else {
            alert('File not found. The link may be invalid or expired.');
            history.replaceState(null, '', window.location.pathname);
            resetDownloadSection();
          }
        } else {
          resetDownloadSection();
        }
      }

      window.addEventListener('load', checkHash);
      window.addEventListener('hashchange', checkHash);
    })();
  </script>
</body>
</html>
